<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue';
import {useRouter} from 'vue-router';
import {api} from '../state';
import {ApiError,type Book} from '../api/client';
import {comicPages,comicImage,type ComicPage} from '../api/comics';
import {parseComicLocator,nextComicPage,comicPercent,canComicSwipe,comicWindow,comicScrollTop,comicScrollPosition} from '../reader/comic';
import {clampComicPan,zoomUnderPointer,shouldWheelZoom,type ZoomBounds} from '../reader/comicZoom';
import {comicDocumentMode,comicDocumentFormat,encodeComicProgress} from '../reader/comicDocument';
import type {DocumentInteraction,DocumentInfo} from '../reader/desktop';
import DocumentReader from './DocumentReader.vue';
const props=defineProps<{book:Book}>(),router=useRouter();
const controls=ref(true);
const jumpPage=ref(1);
const page=ref(1),total=ref(0),fraction=ref(0),direction=ref<'ltr'|'rtl'>('ltr'),mode=ref('paginated'),fit=ref('height'),zoom=ref(1),pan=ref({x:0,y:0});
const busy=ref(true),error=ref(''),notice=ref(''),drawer=ref(false),thumbStart=ref(1),urls=ref<Record<number,string>>({}),thumbs=ref<Record<number,string>>({}),metadata=ref<ComicPage[]>([]),file=ref<Blob>(),documentReader=ref<any>(),pdfLocator=ref('p:1'),viewport=ref<HTMLElement>(),width=ref(800),height=ref(600),conflict=ref<any>(null);
const isDocument=computed(()=>comicDocumentMode(props.book)),documentFormat=computed(()=>comicDocumentFormat(props.book)),isPDF=computed(()=>documentFormat.value==='pdf');
const documentLocator=ref(''),documentPercent=ref(0);
let scrollJump=0,scrollJumpActive=false;
let imageEpoch=0,thumbEpoch=0,pdfLegacyPage=0,pdfSavedRaw='',pdfRestoreBlocked=false,lastTouchAt=0,dragged=false;
let generation=0,loadAbort=new AbortController(),imageAbort=new AbortController(),thumbAbort=new AbortController(),saveAbort=new AbortController(),timer:ReturnType<typeof setTimeout>|undefined,resize:ResizeObserver|undefined,restoring=true,closed=false,saving=false,queued=false,lastTimestamp=0;
const device='comic-web';
const offsets=computed(()=>{const a=[0];for(let i=0;i<total.value;i++){const p=metadata.value[i];a.push(a[i]+(p?width.value*p.height/p.width:height.value)+16)}return a});
const visible=computed(()=>mode.value==='paginated'?[page.value]:comicWindow(page.value,total.value,2));
const thumbVisible=computed(()=>comicWindow(thumbStart.value,total.value,6));
const topSpace=computed(()=>offsets.value[(visible.value[0]??1)-1]??0);
const bottomSpace=computed(()=>Math.max(0,(offsets.value[total.value]??0)-(offsets.value[visible.value.at(-1)??1]??0)));
function revoke(values:Record<number,string>){Object.values(values).forEach(URL.revokeObjectURL)}
function cleanup(){++imageEpoch;++thumbEpoch;loadAbort.abort();imageAbort.abort();thumbAbort.abort();saveAbort.abort();clearTimeout(timer);resize?.disconnect();revoke(urls.value);revoke(thumbs.value);urls.value={};thumbs.value={}}
async function open(){cleanup();const g=++generation;loadAbort=new AbortController();saveAbort=new AbortController();busy.value=true;error.value='';notice.value='';conflict.value=null;restoring=true;pdfRestoreBlocked=false;pdfLegacyPage=0;pdfSavedRaw='';page.value=1;fraction.value=0;total.value=0;metadata.value=[];file.value=undefined;zoom.value=1;pan.value={x:0,y:0};direction.value=(props.book as any).reading_direction==='rtl'?'rtl':'ltr';try{
 const progress=await api.request<any>('/progress/'+props.book.id,{signal:loadAbort.signal});if(g!==generation)return;
 if(isDocument.value){const blob=await api.request<Blob>(`/books/${props.book.id}/file`,{signal:loadAbort.signal,headers:{Accept:'application/octet-stream'}});if(g!==generation)return;file.value=blob;const l=parseComicLocator(progress?.locator||'',props.book.hash);pdfSavedRaw=progress?.updated_at?progress.locator||'':'';const old=/^p:(\d+)$/.exec(pdfSavedRaw);pdfLegacyPage=old?Number(old[1]):0;pdfLocator.value=isPDF.value?'p:'+(l?.page??Math.max(1,pdfLegacyPage)):(l?.document_locator||(/^e:epubcfi\(.+\)$/.test(pdfSavedRaw)?pdfSavedRaw:''));documentLocator.value=pdfLocator.value;documentPercent.value=Number(progress?.percent)||0;if(pdfSavedRaw&&!l&&!old&&!(!isPDF.value&&/^e:epubcfi\(.+\)$/.test(pdfSavedRaw)))notice.value='已保存位置属于旧版本或无法识别，请重新选择页码';}
 else {let cursor:number|null=1;while(cursor){const m=await comicPages(api,props.book.id,cursor,loadAbort.signal);if(g!==generation)return;if(m.edition!==props.book.hash)throw new Error('漫画版本已变化，请返回书库重新打开');total.value=m.total;direction.value=m.direction;metadata.value.push(...m.pages);cursor=m.next_cursor;}const l=parseComicLocator(progress?.locator||'',props.book.hash,total.value);if(l){page.value=l.page;fraction.value=l.y}else if(progress?.updated_at&&progress?.locator)notice.value='已保存位置属于旧版本或无法识别，请重新选择页码';}
 lastTimestamp=Number(progress?.updated_at)||0;await nextTick();if(g!==generation)return;resize=new ResizeObserver(()=>{width.value=viewport.value?.clientWidth||800;height.value=viewport.value?.clientHeight||600;if(mode.value==='scroll')restoreScroll()});if(viewport.value){width.value=viewport.value.clientWidth;height.value=viewport.value.clientHeight;resize.observe(viewport.value)}await refreshImages();if(g!==generation)return;restoreScroll();if(!isDocument.value)restoring=false;
 }catch(e:any){if(g===generation&&e?.name!=='AbortError')error.value=e.message||'加载失败'}finally{if(g===generation)busy.value=false}}
async function refreshImages(){imageAbort.abort();imageAbort=new AbortController();const signal=imageAbort.signal,g=generation,epoch=++imageEpoch;if(isDocument.value||!total.value)return;const wanted=mode.value==='paginated'?comicWindow(page.value,total.value,1):visible.value;const kept:Record<number,string>={};for(const [key,url] of Object.entries(urls.value)){if(wanted.includes(Number(key)))kept[Number(key)]=url;else URL.revokeObjectURL(url)}urls.value=kept;await Promise.all(wanted.map(async n=>{if(urls.value[n])return;try{const blob=await comicImage(api,props.book.id,n,props.book.hash,signal);if(signal.aborted||g!==generation||epoch!==imageEpoch)return;urls.value={...urls.value,[n]:URL.createObjectURL(blob)}}catch(e:any){if(!signal.aborted&&g===generation)error.value=e.message||'页面加载失败'}}))}
async function refreshThumbs(){thumbAbort.abort();thumbAbort=new AbortController();const signal=thumbAbort.signal,g=generation,epoch=++thumbEpoch;revoke(thumbs.value);thumbs.value={};if(!drawer.value||isDocument.value)return;await Promise.all(thumbVisible.value.map(async n=>{try{const blob=await comicImage(api,props.book.id,n,props.book.hash,signal,true);if(!signal.aborted&&g===generation&&epoch===thumbEpoch)thumbs.value={...thumbs.value,[n]:URL.createObjectURL(blob)}}catch{/* full page remains available */}}))}
function restoreScroll(){if(mode.value==='scroll'&&!isDocument.value&&viewport.value)viewport.value.scrollTop=comicScrollTop(offsets.value,page.value,fraction.value)}
async function go(n:number){pdfRestoreBlocked=false;const wanted=Math.max(1,Math.min(total.value||1,Math.floor(n)||1)),jump=++scrollJump;scrollJumpActive=mode.value==='scroll'&&!isDocument.value;jumpPage.value=wanted;page.value=wanted;fraction.value=0;zoom.value=1;pan.value={x:0,y:0};if(isDocument.value){if(isPDF.value)await documentReader.value?.goTo('p:'+page.value);else await documentReader.value?.goToSection(page.value-1)}else{await nextTick();if(closed||jump!==scrollJump)return;page.value=wanted;fraction.value=0;restoreScroll();void refreshImages();if(scrollJumpActive)requestAnimationFrame(()=>requestAnimationFrame(()=>{if(closed||jump!==scrollJump)return;restoreScroll();scrollJumpActive=false}))}scheduleSave()}
function turn(delta:number){if(isDocument.value&&!isPDF.value){zoom.value=1;pan.value={x:0,y:0};void(delta>0?documentReader.value?.next():documentReader.value?.prev());return}void go(page.value+delta)}
function scroll(){if(mode.value!=='scroll'||isDocument.value||restoring||scrollJumpActive||!viewport.value)return;const p=comicScrollPosition(offsets.value,viewport.value.scrollTop);const changed=p.page!==page.value;page.value=p.page;fraction.value=p.y;if(changed)void refreshImages();scheduleSave()}
function scheduleSave(){if(restoring||pdfRestoreBlocked||conflict.value)return;clearTimeout(timer);timer=setTimeout(()=>void save(),400)}
async function save(override=0){if(restoring||closed||!total.value||conflict.value&&!override)return;if(saving){queued=true;return}saving=true;const g=generation,id=props.book.id;const body={locator:encodeComicProgress({edition:props.book.hash,page:page.value,y:fraction.value,...(isDocument.value&&!isPDF.value&&documentLocator.value?{document_locator:documentLocator.value}:{})}),chapter_idx:page.value-1,percent:isDocument.value&&!isPDF.value?documentPercent.value:comicPercent(page.value,fraction.value,total.value),device_id:device,updated_at:Math.max(Date.now(),lastTimestamp+1,override)};if(!body.locator){saving=false;notice.value='当前文档定位过长，未同步此位置';return}lastTimestamp=body.updated_at;try{const result=await api.request<any>('/progress/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:saveAbort.signal});if(g===generation){lastTimestamp=result?.updated_at??body.updated_at;notice.value='进度已同步';conflict.value=null}}catch(e:any){if(g!==generation||e.name==='AbortError')return;if(e instanceof ApiError&&e.status===409){conflict.value=e.body?.error?.current??e.body?.current??e.body?.progress??{};notice.value='其他设备的进度已变化，请选择保留的位置'}else notice.value='进度同步失败，请检查连接'}finally{saving=false;if(queued){queued=false;scheduleSave()}}}
async function useRemote(){try{const p=await api.request<any>('/progress/'+props.book.id,{signal:loadAbort.signal});const l=parseComicLocator(p?.locator||'',props.book.hash,total.value);if(!l){notice.value='服务器位置属于旧版本，无法恢复';return}restoring=true;lastTimestamp=p.updated_at;conflict.value=null;if(isDocument.value&&!isPDF.value&&l.document_locator){documentLocator.value=l.document_locator;await documentReader.value?.goTo(l.document_locator)}else await go(l.page);fraction.value=l.y;restoreScroll();restoring=false;notice.value='已使用服务器进度'}catch(e:any){notice.value=e.message}}
async function retainLocal(){const p=await api.request<any>('/progress/'+props.book.id,{signal:loadAbort.signal});await save(Math.max(Date.now(),Number(p?.updated_at||0)+1))}
function key(e:KeyboardEvent){if(e.altKey||e.ctrlKey||e.metaKey||e.shiftKey||(e.target as HTMLElement)?.closest('input,select,textarea,button'))return;if(isDocument.value&&!isPDF.value&&['ArrowLeft','ArrowRight','PageUp','PageDown'].includes(e.key)){e.preventDefault();turn(e.key==='PageDown'?1:e.key==='PageUp'?-1:(e.key==='ArrowRight')===(direction.value==='ltr')?1:-1);return}let n=page.value;if(e.key==='ArrowLeft')n=nextComicPage(n,total.value,direction.value,'right');else if(e.key==='ArrowRight')n=nextComicPage(n,total.value,direction.value,'left');else if(e.key==='PageDown')n++;else if(e.key==='PageUp')n--;else return;e.preventDefault();void go(n)}
let touch:{x:number;y:number;panX:number;panY:number;distance:number;scale:number;count:number;pinched:boolean}|null=null;
function start(e:TouchEvent){lastTouchAt=Date.now();const t=e.touches[0];if(!t)return;touch={x:t.clientX,y:t.clientY,panX:pan.value.x,panY:pan.value.y,distance:e.touches.length>1?Math.hypot(e.touches[1].clientX-t.clientX,e.touches[1].clientY-t.clientY):0,scale:zoom.value,count:e.touches.length,pinched:e.touches.length>1}}
function move(e:TouchEvent){if(!touch)return;const t=e.touches[0];if(!t)return;if(e.touches.length>1){touch.pinched=true;if(!touch.distance){touch.distance=Math.hypot(e.touches[1].clientX-t.clientX,e.touches[1].clientY-t.clientY);touch.scale=zoom.value}zoom.value=Math.min(4,Math.max(1,touch.scale*Math.hypot(e.touches[1].clientX-t.clientX,e.touches[1].clientY-t.clientY)/Math.max(1,touch.distance)));e.preventDefault()}else if(zoom.value>1){pan.value=clampComicPan({x:touch.panX+t.clientX-touch.x,y:touch.panY+t.clientY-touch.y},zoom.value,zoomBounds());e.preventDefault()}}
function end(e:TouchEvent){const s=touch;touch=null;const t=e.changedTouches[0];if(s&&t&&!s.pinched&&zoom.value===1&&Math.hypot(t.clientX-s.x,t.clientY-s.y)<12){toggleAt(t.clientX);return}if(!s||!t||mode.value!=='paginated'||!canComicSwipe(s.count,zoom.value,s.pinched))return;const dx=t.clientX-s.x,dy=t.clientY-s.y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)void go(nextComicPage(page.value,total.value,direction.value,dx<0?'left':'right'))}
let mouse:{x:number;y:number;px:number;py:number}|null=null;
function mouseStart(e:MouseEvent){dragged=false;if(zoom.value<=1||e.button!==0)return;mouse={x:e.clientX,y:e.clientY,px:pan.value.x,py:pan.value.y};e.preventDefault()}
function mouseMove(e:MouseEvent){if(!mouse)return;dragged=true;pan.value=clampComicPan({x:mouse.px+e.clientX-mouse.x,y:mouse.py+e.clientY-mouse.y},zoom.value,zoomBounds())}
function pdfProgress(p:any){if(!total.value)return;if(!isPDF.value){documentLocator.value=p.locator;documentPercent.value=p.percent;}page.value=p.chapter_idx+1;fraction.value=0;scheduleSave()}
function documentInfo(info:DocumentInfo){if(!isPDF.value)total.value=info.sections}
function documentReady(value:{busy:boolean}){if(!value.busy&&!error.value){restoring=false;scheduleSave()}}
function pdfToc(t:any[]){if(!isPDF.value)return;total.value=t.length;const l=parseComicLocator(pdfSavedRaw,props.book.hash,t.length);if(pdfLegacyPage){if(pdfLegacyPage<=t.length){page.value=pdfLegacyPage;pdfLocator.value='p:'+pdfLegacyPage;notice.value='已恢复此前 PDF 的第 '+pdfLegacyPage+' 页位置'}else{pdfRestoreBlocked=true;page.value=1;pdfLocator.value='p:1';notice.value='已保存页码超出当前 PDF 范围'}}else if(l){page.value=l.page;pdfLocator.value='p:'+l.page;fraction.value=l.y}else if(pdfSavedRaw){pdfRestoreBlocked=true;page.value=1;pdfLocator.value='p:1';notice.value='已保存位置属于旧版本或超出当前 PDF 范围'}restoring=false}
function zoomBounds():ZoomBounds{const view=viewport.value,img=view?.querySelector<HTMLImageElement>(`[data-page="${page.value}"] img`),canvas=view?.querySelector<HTMLCanvasElement>('canvas');const target=img||canvas;return {viewWidth:view?.clientWidth||width.value,viewHeight:view?.clientHeight||height.value,contentWidth:target?.clientWidth||view?.clientWidth||width.value,contentHeight:target?.clientHeight||view?.clientHeight||height.value}}
function wheel(e:WheelEvent){if(!viewport.value||!shouldWheelZoom(mode.value,e.ctrlKey,e.metaKey,!!(e.target as HTMLElement)?.closest?.('button,a,input,select,textarea,.comic-drawer,.comic-settings')))return;e.preventDefault();applyWheel(e.clientX,e.clientY,e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?height.value:1))}
function applyWheel(x:number,y:number,delta:number){const rect=viewport.value?.getBoundingClientRect();if(!rect)return;const next=zoomUnderPointer({zoom:zoom.value,pan:pan.value},{x:x-rect.left-rect.width/2,y:y-rect.top-rect.height/2},delta,zoomBounds());zoom.value=next.zoom;pan.value=next.pan}
function documentInteraction(event:DocumentInteraction){if(event.kind==='wheel')applyWheel(event.x??0,event.y??0,event.deltaY??0);else if(event.kind==='tap')toggleAt(event.x??0);else if(event.kind==='key'&&event.key)key(new KeyboardEvent('keydown',{key:event.key}))}
function toggleAt(x:number){const r=viewport.value?.getBoundingClientRect();if(r&&x>r.left+r.width*.3&&x<r.left+r.width*.7&&!window.getSelection()?.toString())controls.value=!controls.value}
function click(e:MouseEvent){if(dragged||Date.now()-lastTouchAt<700||(e.target as HTMLElement)?.closest('button,a,input,select'))return;toggleAt(e.clientX)}
function flush(){if(restoring||pdfRestoreBlocked||!total.value||conflict.value)return;const body={locator:encodeComicProgress({edition:props.book.hash,page:page.value,y:fraction.value,...(isDocument.value&&!isPDF.value&&documentLocator.value?{document_locator:documentLocator.value}:{})}),chapter_idx:page.value-1,percent:isDocument.value&&!isPDF.value?documentPercent.value:comicPercent(page.value,fraction.value,total.value),device_id:device,updated_at:Math.max(Date.now(),lastTimestamp+1)};if(!body.locator)return;void api.request('/progress/'+props.book.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),keepalive:true}).catch(()=>{});}
watch(page,value=>{jumpPage.value=value});watch(()=>props.book.id,open,{immediate:true});watch([mode,fit],async()=>{zoom.value=1;pan.value={x:0,y:0};await nextTick();restoreScroll();void refreshImages()});watch([drawer,thumbStart],refreshThumbs);watch(zoom,()=>{pan.value=clampComicPan(pan.value,zoom.value,zoomBounds())});
onBeforeUnmount(()=>{flush();closed=true;++generation;cleanup()});
</script>
<template>
<section class="comic-reader" tabindex="0" @keydown="key" aria-label="漫画阅读器">
<header v-show="controls" class="comic-toolbar"><button @click="router.push('/comics')">返回漫画库</button><strong>{{book.title}}</strong><button @click="drawer=!drawer" :aria-expanded="drawer">页码目录</button></header>
<div v-show="controls" class="comic-settings"><label>布局 <select v-model="mode"><option value="paginated">单页</option><option value="scroll">连续竖滚</option></select></label><label>适应 <select v-model="fit"><option value="height">适高</option><option value="width">适宽</option></select></label><label>方向 <select v-model="direction"><option value="ltr">从左到右</option><option value="rtl">从右到左</option></select></label><label>缩放 <input aria-label="缩放" type="range" min="1" max="4" step="0.1" v-model.number="zoom"></label><button @click="zoom=1;pan={x:0,y:0}">重置</button></div>
<p v-if="controls" class="zoom-hint">{{mode==='scroll'?'滚轮正常滚动，Ctrl/Command + 滚轮缩放':'滚轮以鼠标位置为中心缩放，放大后拖动查看'}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><div v-if="conflict" class="conflict" role="alert"><p>其他设备已保存新的阅读位置</p><button @click="useRemote">使用服务器进度</button><button @click="retainLocal">保留当前进度</button></div>
<p v-if="error" role="alert">{{error}} <button @click="open">重试</button></p><p v-if="busy" role="status">正在加载漫画…</p>
<div ref="viewport" class="comic-viewport" :style="{'--comic-view-height':height+'px'}" :class="{continuous:mode==='scroll',zoomed:zoom>1}" @scroll="scroll" @wheel="wheel" @click="click" @mousedown="mouseStart" @mousemove="mouseMove" @mouseup="mouse=null" @mouseleave="mouse=null" @touchstart="start" @touchmove="move" @touchend="end" @touchcancel="touch=null">
<DocumentReader v-if="isDocument&&file" ref="documentReader" :class="{'pdf-fit-height':fit==='height'&&mode==='paginated'}" :style="{transform:`translate(${pan.x}px,${pan.y}px) scale(${zoom})`}" :file="file" :format="documentFormat" :locator="pdfLocator" :wheel-zoom="mode==='scroll'?'scroll':'paginated'" theme="dark" :size="18" :line-height="1.8" font="sans-serif" :mode="mode" @toc="pdfToc" @document-info="documentInfo" @speech-ready="documentReady" @interaction="documentInteraction" @progress="pdfProgress" @error="error=$event" />
<template v-else-if="total"><div v-if="mode==='scroll'" :style="{height:topSpace+'px',flexShrink:0}"></div><div v-for="n in visible" :key="n" class="comic-sheet" :class="{'fit-width':fit==='width'&&mode==='paginated'}" :data-page="n" :style="mode==='scroll'?{height:((offsets[n]??0)-(offsets[n-1]??0)-16)+'px',marginBottom:'16px'}:{}"><img v-if="urls[n]" :src="urls[n]" :alt="'第 '+n+' 页'" :class="[fit,mode]" :style="{transform:`translate(${pan.x}px,${pan.y}px) scale(${zoom})`}" draggable="false"><span v-else>正在加载第 {{n}} 页…</span></div><div v-if="mode==='scroll'" :style="{height:bottomSpace+'px',flexShrink:0}"></div></template>
</div>
<footer v-show="controls" class="comic-toolbar"><button @click="turn(-1)" :disabled="isDocument&&!isPDF?documentPercent<=0:page<=1">上一页</button><label><input aria-label="跳转页码" type="number" v-model.number="jumpPage" min="1" :max="total" @change="go(Number(jumpPage))"> / {{total}} {{isDocument&&!isPDF?'节':'页'}}</label><button @click="turn(1)" :disabled="isDocument&&!isPDF?documentPercent>=1:page>=total">下一页</button></footer>
<aside v-if="drawer" class="comic-drawer" aria-label="页码目录"><header><strong>页码目录</strong><button @click="drawer=false">关闭目录</button></header><label>目录起始页 <input type="number" v-model.number="thumbStart" min="1" :max="total"></label><div class="thumb-grid"><button v-for="n in thumbVisible" :key="n" :aria-current="n===page?'page':undefined" @click="go(n);drawer=false"><img v-if="thumbs[n]" :src="thumbs[n]" alt="">第 {{n}} 页</button></div><button @click="thumbStart=Math.max(1,thumbStart-12)" :disabled="thumbStart<=1">前一组</button><button @click="thumbStart=Math.min(total,thumbStart+12)" :disabled="thumbStart>=total">后一组</button></aside>
</section>
